package au.org.regeneratus.augury.core

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Kotlin ↔ Python parity against fixtures generated by
 * `augury-android/tools/emit_golden_fixtures.py`.
 *
 * The fixtures are not hand-written expectations: the generator runs the **real**
 * `scripts/species_lookup.py`, `scripts/augury_funnel.py`, `scripts/intent.py`
 * and `scripts/grounding.py` over the **same** database the app ships
 * (`data/app/augury-ondevice.json`) and records what they produced. Every
 * assertion below is a comparison against that recorded behaviour.
 */
class GoldenParityTest {

    private val store get() = AuguryTestSupport.store
    private val composer = StoryComposer()

    // ── the database the fixture was built from ─────────────────────────────

    @Test
    fun `fixture describes the same database the app loads`() {
        val counts = AuguryTestSupport.map(AuguryTestSupport.golden["counts"])
        assertEquals(2256, AuguryTestSupport.num(counts["species"]).toInt())
        assertEquals(2256, store.speciesCount)
        assertEquals(
            "common-name index size",
            AuguryTestSupport.num(counts["common_names"]).toInt(),
            store.commonNameCount,
        )
        assertEquals(
            "curated synonym count",
            AuguryTestSupport.num(counts["curated_synonyms"]).toInt(),
            store.curatedSynonymCount,
        )
        assertEquals(1, AuguryTestSupport.num(counts["schema"]).toInt())
        assertEquals(
            AuguryTestSupport.strings(AuguryTestSupport.golden["junk_keys"]).toSet(),
            SpeciesStore.JUNK_KEYS,
        )
        assertEquals(
            AuguryTestSupport.strings(AuguryTestSupport.golden["clay_pseudo_species"]).toSet(),
            SpeciesStore.CLAY_PSEUDO_SPECIES,
        )
    }

    // ── db probes: search, canonical group, full indicator payload ──────────

    @Test
    fun `every db probe matches the python reference exactly`() {
        val probes = AuguryTestSupport.goldenList("db_probes")
        assertEquals("fixture should carry all db probes", 110, probes.size)

        var searchComparisons = 0
        var groupComparisons = 0
        var resultComparisons = 0
        val unresolvable = ArrayList<String>()

        for (probe in probes) {
            val query = AuguryTestSupport.str(probe["query"])!!
            val region = AuguryTestSupport.str(probe["region"])
            val label = "'$query' @ ${region ?: "<default>"}"

            // 1. search() — every hit, in order, with its score.
            val expectedSearch = AuguryTestSupport.maps(probe["search_all"])
            val actualSearch = store.search(query, 5)
            assertEquals("$label search hit count", expectedSearch.size, actualSearch.size)
            expectedSearch.forEachIndexed { i, e ->
                assertEquals("$label search[$i].key", AuguryTestSupport.str(e["key"]), actualSearch[i].key)
                assertEquals("$label search[$i].match_type", AuguryTestSupport.str(e["match_type"]), actualSearch[i].matchType)
                assertEquals("$label search[$i].score", AuguryTestSupport.num(e["score"]), actualSearch[i].score, 0.0)
                searchComparisons += 3
            }

            // 2. canonical group.
            val expectedGroup = AuguryTestSupport.strings(probe["canonical_group"])
            val actualGroup = store.canonicalGroup(query.trim().lowercase())
            assertEquals("$label canonical_group", expectedGroup, actualGroup)
            groupComparisons++

            // 3. get_indicators() — verbatim.
            val expected = probe["result"]
            val actual = store.resolveQuery(query, region)
            if (expected == null) {
                assertNull("$label should not resolve", actual)
                unresolvable.add(query)
                continue
            }
            assertNotNull("$label should resolve", actual)
            val r = actual!!
            val e = AuguryTestSupport.map(expected)
            assertEquals("$label scientific_name", AuguryTestSupport.str(e["scientific_name"]), r.scientificName)
            assertEquals("$label common_names", AuguryTestSupport.strings(e["common_names"]), r.commonNames)
            assertEquals("$label region", AuguryTestSupport.str(e["region"]), r.region)
            assertEquals("$label requested_region", AuguryTestSupport.str(e["requested_region"]), r.requestedRegion)
            assertEquals("$label region_fallback", AuguryTestSupport.bool(e["region_fallback"]), r.regionFallback)
            assertEquals("$label indicators (order sensitive)", AuguryTestSupport.indicators(e["indicators"]), r.indicators)
            assertEquals("$label indicator key order", AuguryTestSupport.indicators(e["indicators"]).keys.toList(), r.indicators.keys.toList())
            assertEquals("$label source", AuguryTestSupport.str(e["source"]), r.source)
            assertEquals("$label canonical_key", AuguryTestSupport.str(e["canonical_key"]), r.canonicalKey)
            assertEquals("$label merged_from", AuguryTestSupport.strings(e["merged_from"]), r.mergedFrom)
            assertEquals("$label specificity", AuguryTestSupport.str(e["specificity"]), r.specificity)
            val em = AuguryTestSupport.map(e["match"])
            assertEquals("$label match.match_type", AuguryTestSupport.str(em["match_type"]), r.match.matchType)
            assertEquals("$label match.score", AuguryTestSupport.num(em["score"]), r.match.score, 0.0)
            resultComparisons += 12
        }

        // CORRECTED EXPECTATION (was `assertTrue(nullResults >= 5)`): exactly four
        // of the fixture's 110 probes carry a null result, and naming them makes a
        // fifth a deliberate, visible delta rather than a silent pass. Three are
        // known to the DB but carry no indicator rows anywhere; the fourth is
        // simply unknown, and none of the four has a reachable search() hit that
        // the reference resolves (e.g. "asdfghjkl qwerty" has an empty search_all).
        // Verified by re-running tools/emit_golden_fixtures.py: the regenerated
        // db_probes are byte-identical to the committed fixture, so this is the
        // reference's own count, not a stale one.
        assertEquals(
            "the fixture's unresolvable probes",
            listOf("bothriochloa macra", "cheilanthes sieberi", "glycine tabacina", "asdfghjkl qwerty"),
            unresolvable,
        )
        assertTrue("search comparisons", searchComparisons > 200)
        assertTrue("group comparisons", groupComparisons == 110)
        assertTrue("result comparisons", resultComparisons > 900)
    }

    // ── story probes: the rendered user-facing text ─────────────────────────

    @Test
    fun `every story probe matches the python template byte for byte`() {
        val probes = AuguryTestSupport.goldenList("story_probes")
        assertEquals(11, probes.size)
        var stories = 0
        var noneCases = 0

        for (probe in probes) {
            val names = AuguryTestSupport.strings(probe["names"])
            val region = AuguryTestSupport.str(probe["region"])
            val expectedKeys = AuguryTestSupport.strings(probe["resolved_keys"])
            val expectedSpecies = AuguryTestSupport.strings(probe["species"])
            val pythonStory = AuguryTestSupport.str(probe["python_composed_story"])!!
            val noneKeys = AuguryTestSupport.strings(probe["indicator_keys_with_none"])
            val label = "${names.ifEmpty { listOf("<none>") }} @ $region"

            val resolved = names.mapNotNull { store.resolveQuery(it, region) }
            assertEquals("$label resolved keys", expectedKeys, resolved.map { it.match.key })
            assertEquals("$label species", expectedSpecies, resolved.map { it.scientificName })

            val actual = composer.compose(resolved, names.joinToString(" "), region)
            val expected = stripNoneValues(pythonStory, resolved)
            assertEquals("$label story", expected, actual)

            if (noneKeys.isNotEmpty()) {
                noneCases++
                // Prove the deviation is real rather than vacuous: Python's own
                // template does render a "none" row, and the port does not.
                for (k in noneKeys) {
                    assertTrue("python story should contain a '$k' row", pythonStory.contains("📋 **$k:**"))
                    assertTrue("kotlin story must not render '$k: none'", !actual.contains("📋 **$k:** none"))
                }
            }
            stories++
        }
        assertEquals(11, stories)
        assertTrue("expected at least one 'none' probe", noneCases >= 1)
    }

    @Test
    fun `the no-species story is the python refusal text`() {
        val probe = AuguryTestSupport.goldenList("story_probes").first { AuguryTestSupport.strings(it["names"]).isEmpty() }
        assertEquals(
            AuguryTestSupport.str(probe["python_composed_story"]),
            composer.compose(emptyList(), "", AuguryTestSupport.str(probe["region"])),
        )
    }

    // ── message probes: intent, refusal and the whole answer ────────────────

    @Test
    fun `every message probe answers exactly like the python funnel`() {
        val probes = AuguryTestSupport.goldenList("message_probes")
        assertTrue("expected the full message probe set", probes.size >= 16)
        val answerer = AuguryAnswerer(store, composer)
        var comparisons = 0

        for (probe in probes) {
            val message = AuguryTestSupport.str(probe["message"])!!
            val region = AuguryTestSupport.str(probe["region"])
            val supplied = AuguryTestSupport.strings(probe["supplied_species"])
            val expected = AuguryTestSupport.map(probe["expected"])
            val label = "'${message.ifEmpty { "<empty>" }}' @ $region"

            val payload = answerer.answer(message, supplied, region)

            assertEquals("$label refused", AuguryTestSupport.bool(expected["refused"]), payload.refused)
            assertEquals("$label refused_reason", AuguryTestSupport.str(expected["refused_reason"]), payload.refusedReason)
            assertEquals("$label intent", AuguryTestSupport.str(expected["intent"]), payload.intent)
            assertEquals("$label species", AuguryTestSupport.strings(expected["species"]), payload.species)
            assertEquals(
                "$label response",
                stripNoneValues(AuguryTestSupport.str(expected["response"])!!, payload.resolved),
                payload.response,
            )

            // The seven contract keys must always be present and consistent.
            assertEquals(payload.refused, payload.refusedReason != null)
            if (payload.refused) {
                assertTrue("$label refused payloads carry no species", payload.species.isEmpty())
                assertTrue("$label refused payloads carry no matches", payload.matches.isEmpty())
                assertTrue("$label refused payloads carry no repairs", payload.groundingRepairs.isEmpty())
            } else {
                assertNull(payload.refusedReason)
                assertEquals(payload.species.size, payload.matches.size)
                assertEquals(payload.species.size, payload.resolved.size)
            }
            comparisons += 6
        }
        assertTrue(comparisons >= 96)
    }

    @Test
    fun `the python funnel cross-check agrees on every overlapping outcome`() {
        // The fixture also records the real funnel running on the *training*
        // database. Where both databases resolve, the outcome (refused / reason /
        // intent) must agree; the scientific names legitimately differ where the
        // two databases disagree about a name.
        var compared = 0
        for (probe in AuguryTestSupport.goldenList("message_probes")) {
            val python = AuguryTestSupport.map(probe["python_funnel"])
            if (python.isEmpty()) continue
            val expected = AuguryTestSupport.map(probe["expected"])
            assertEquals("refused", AuguryTestSupport.bool(python["refused"]), AuguryTestSupport.bool(expected["refused"]))
            assertEquals("refused_reason", AuguryTestSupport.str(python["refused_reason"]), AuguryTestSupport.str(expected["refused_reason"]))
            assertEquals("intent", AuguryTestSupport.str(python["intent"]), AuguryTestSupport.str(expected["intent"]))
            compared += 3
        }
        assertTrue("expected the python funnel cross-check to be present", compared >= 45)
    }

    // ── helpers ─────────────────────────────────────────────────────────────

    /**
     * Remove the rows the Kotlin renderer deliberately skips
     * ([StoryComposer.NONE_VALUE_DEVIATION]) from a Python-rendered story.
     *
     * Each row is emitted as `"\n📋 **key:** value"`, so the exact segment is
     * removed rather than a line, which keeps the blank-line spacing identical.
     */
    private fun stripNoneValues(
        pythonStory: String,
        resolved: List<SpeciesStore.ResolvedSpecies>,
    ): String {
        var out = pythonStory
        for (r in resolved) {
            for ((k, v) in r.indicators) {
                if (v.trim().lowercase() == "none") out = out.replace("\n📋 **$k:** $v", "")
            }
        }
        return out
    }
}
